-- Perfect Store / FrieslandCampina : territoires x areas x distributeur
-- Source: 'BIG FIVE KPI UPDATE vf.xlsx' (TERRITORY + Mapping)
-- 1 ligne = 1 zone x 1 distributeur. Port bouet duplique (SDTP + SDHPA).

create table if not exists public.territory_areas (
  id                bigint generated always as identity primary key,
  country_code text, country_name text,
  region_code text, region_label text, region_name text,
  sub_region_code text, sub_region_label text, sub_region_name text,
  territory_code text, territory_name text,
  area_code text, area_name text, distributor text
);

create index if not exists idx_ta_territory on public.territory_areas (territory_code);
create index if not exists idx_ta_distrib   on public.territory_areas (distributor);









